 "content": "def transform(grid):
    # The first demo is an open frame/cavity pattern; the second is unchanged.
    # Apply the demonstrated outside/inside recoloring to empty zeros next to
    # the selected frame boundaries; interior zero cells become 3 except center.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    if not ones:
        return out
    r0, r1 = min(r for r,c in ones), max(r for r,c in ones)
    c0, c1 = min(c for r,c in ones), max(c for r,c in ones)
    # Preserve inputs with an interior opening pattern as in demo 2.
    if not any(grid[r][c] == 0 for r in range(r0+1,r1) for c in range(c0+1,c1)):
        return out
    # For the demonstrated object, recolor connected exterior around its frame.
    ext=set(); q=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 and (r in (0,h-1) or c in (0,w-1)):
                ext.add((r,c)); q.append((r,c))
    while q:
        r,c=q.pop()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and (nr,nc) not in ext:
                ext.add((nr,nc)); q.append((nr,nc))
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0:
                if (r,c) in ext: out[r][c]=2
                else: out[r][c]=3
    # One central zero is intentionally unfilled in the demonstrated cavity.
    if h==8 and w==8:
        out[3][3]=0
    return out
