 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Identify 4-connected zero components. Cavities enclosed by 1s are
    # colored 3, except their unmarked center zero(s); neighboring exterior
    # background is colored 2 along the object's outline.
    seen = set()
    exterior = set()
    cavities = []
    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] != 0 or (sr, sc) in seen:
                continue
            stack = [(sr, sc)]
            seen.add((sr, sc))
            comp = []
            touches_edge = False
            while stack:
                r, c = stack.pop()
                comp.append((r, c))
                if r == 0 or c == 0 or r == h - 1 or c == w - 1:
                    touches_edge = True
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            if touches_edge:
                exterior.update(comp)
            else:
                cavities.append(comp)

    for comp in cavities:
        # Preserve internal zero markers that touch no part of the 1-boundary.
        boundary = set()
